INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Abklären terminlicher Aspekte Teil der Initiierung?', 2, '[{"text": "Ja", "correct": true, "because": "Zeitrahmen wird früh definiert"}, {"text": "Nein", "correct": false, "because": "Es gehört zur Initiierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat das Abklären terminlicher Aspekte?', 3, '[{"text": "Realistischen Zeitplan schaffen", "correct": true, "because": "Legt Zeitbasis"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten sofort senken", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Terminliche Aspekte beeinflussen die Planung. b) Sie werden erst in der Durchführung geklärt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Initiierung ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren werden bei der terminlichen Abklärung berücksichtigt?', 4, '[{"text": "Projektumfang", "correct": true, "because": "Beeinflusst Dauer"}, {"text": "Teamdynamik", "correct": false, "because": "Kein direkter Zeitfaktor"}, {"text": "Verfügbare Ressourcen", "correct": true, "because": "Bestimmen Zeit"}, {"text": "Meilensteine", "correct": true, "because": "Strukturieren Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne terminliche Abklärung starten?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitrahmen fehlt"}, {"text": "Ja", "correct": false, "because": "Risiko von Verzögerungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft beim Abklären terminlicher Aspekte?', 3, '[{"text": "Zeitplanerstellung", "correct": true, "because": "Definiert Deadlines"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Übersicht"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die terminliche Abklärung nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen Zeitrahmen"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher terminlicher Aspekt ist in der Initiierung entscheidend?', 3, '[{"text": "Projektenddatum", "correct": true, "because": "Setzt Zieltermin"}, {"text": "Teamverfügbarkeit", "correct": false, "because": "Späterer Schritt"}, {"text": "Kostenübersicht", "correct": false, "because": "Wirtschaftlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Terminliche Abklärung prüft Machbarkeit. b) Sie ist unwichtig für IT-Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch IT braucht Zeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Abklärung terminlicher Aspekte?', 3, '[{"text": "Verzögerungen entstehen", "correct": true, "because": "Zeitplan fehlt"}, {"text": "Projekt wird effizienter", "correct": false, "because": "Eher Chaos"}, {"text": "Kosten sinken", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können terminliche Aspekte in der Initiierung offen bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Klarheit ist nötig"}, {"text": "Ja", "correct": false, "because": "Verwirrung droht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine terminliche Abklärung?', 3, '[{"text": "App bis 30. Juni fertigstellen", "correct": true, "because": "Klarer Zeitrahmen"}, {"text": "Irgendwann etwas machen", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Kein Termin"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die terminliche Abklärung nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Team braucht Zeitvorgaben"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur terminlichen Abklärung?', 4, '[{"text": "Startdatum", "correct": true, "because": "Beginn festlegen"}, {"text": "Unklare Schätzung", "correct": false, "because": "Fehlt Präzision"}, {"text": "Enddatum", "correct": true, "because": "Zieltermin setzen"}, {"text": "Zwischenziele", "correct": true, "because": "Strukturieren Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die terminliche Abklärung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die terminliche Abklärung?', 3, '[{"text": "Zeitliche Orientierung geben", "correct": true, "because": "Fördert Planung"}, {"text": "Technische Lösung finden", "correct": false, "because": "Anderer Fokus"}, {"text": "Kosten reduzieren", "correct": false, "because": "Unabhängig davon"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die terminliche Abklärung ohne Ressourcenplanung erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Ressourcen beeinflussen Zeit"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die terminliche Abklärung?', 3, '[{"text": "Unklarer Projektumfang", "correct": true, "because": "Verhindert Zeitplan"}, {"text": "Klares Team", "correct": false, "because": "Fördert Abklärung"}, {"text": "Gute Datenbasis", "correct": false, "because": "Unterstützt Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Terminliche Abklärung prüft Zeitressourcen. b) Sie erfolgt erst nach Projektstart.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, vor Start nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel der terminlichen Abklärung?', 3, '[{"text": "Zeitliche Machbarkeit sichern", "correct": true, "because": "Verhindert Verzögerung"}, {"text": "Team motivieren", "correct": false, "because": "Anderer Fokus"}, {"text": "Technische Details klären", "correct": false, "because": "Späterer Schritt"}]');
